{"candidate": {"label": "droopy", "description": "This means carrying one's body slumped and limp, with shoulders sagging and face and features hanging loosely, as though worn down by fatigue or indifference."},
 "traits": [
  {"id": 1, "label": "morose", "description": "This means keeping a sullen, dour mood and withdrawing into silence, showing little willingness to talk and answering others, when one answers at all, with grudging short replies."}
 ]}

{"candidate": {"label": "puny", "description": "This means being physically weak and frail, with little strength or stamina for everyday exertion and a body that gives out easily."},
 "traits": [
  {"id": 1, "label": "mobility impaired", "description": "This means walking with difficulty or not at all: getting around by wheelchair, walker, crutches or cane, taking the ramp and the elevator, and checking a place for steps before going."}
 ]}

{"candidate": {"label": "decayed", "description": "This means being physically wasted, frail, and deteriorated, one's body and strength worn away until little vigor remains in one's frame."},
 "traits": [
  {"id": 1, "label": "elderly", "description": "This means being in one's seventies or beyond, with most of life behind one, a slowing body, grandchildren, and a lifetime of change seen firsthand."}
 ]}

{"candidate": {"label": "buff", "description": "This means keeping one's body muscular and physically fit through regular training, and taking pride in its strength and conditioning as a visible part of who one is."},
 "traits": [
  {"id": 1, "label": "healthy", "description": "This means having a sound constitution: shaking off whatever is going around in a day, no prescriptions, a clean checkup every time, and no sick days in years."}
 ]}

{"candidate": {"label": "nimble", "description": "This means moving quickly and lightly, with easy agility of body, so that one's footwork stays sure and one changes direction without effort or stumbling."},
 "traits": [
  {"id": 1, "label": "energetic", "description": "This means being reliably energetic: full of get-up-and-go, moving and talking at a brisk pace, and taking on task after task without running down."}
 ]}

{"candidate": {"label": "fleet", "description": "This means moving quickly and lightly, covering ground on foot with speed and ease whenever a task calls for it."},
 "traits": [
  {"id": 1, "label": "slight", "description": "This means carrying little muscle on a light frame, whatever one weighs: narrow shoulders and thin wrists, a suitcase that takes both hands, and jar lids that will not budge."},
  {"id": 2, "label": "deft", "description": "This means handling tasks with a quick, skilled touch, working with one's hands in a way that is precise, nimble and easy to watch."}
 ]}

{"candidate": {"label": "ambidextrous", "description": "This means handling tasks with either hand equally well, switching between left and right without favoring one, so that writing, cutting, throwing and tool use feel just as natural on either side."},
 "traits": [
  {"id": 1, "label": "competent", "description": "This means knowing how to do the job and getting it right, handling the task in front of one with sure hands, and turning out work that holds up."},
  {"id": 2, "label": "deft", "description": "This means handling tasks with a quick, skilled touch, working with one's hands in a way that is precise, nimble and easy to watch."}
 ]}

{"candidate": {"label": "homely", "description": "This means being plain of face and figure, with looks that draw no admiring attention and that one accepts without fuss."},
 "traits": [
  {"id": 1, "label": "dull", "description": "This means having a presence that draws no one in, talking without confidence or charm, so that even good ideas sound lifeless and conversations soon peter out."},
  {"id": 2, "label": "unassuming", "description": "This means no flourish, no performance, no commanding the room, just the point made quietly in plain words by someone who would rather go unnoticed."}
 ]}

{"candidate": {"label": "squeaky", "description": "This means speaking in a high, thin, squeaky voice that carries a shrill, reedy quality through every sentence one says."},
 "traits": [
  {"id": 1, "label": "ethereal", "description": "This means communicating with an otherworldly, delicate quality that seems barely connected to physical reality, like something floating between dreams and the material world."}
 ]}

{"candidate": {"label": "voiceless", "description": "This means being unable to speak at all, so that every message one conveys must come through gesture, writing, or other silent means."},
 "traits": [
  {"id": 1, "label": "emotionally-inarticulate", "description": "This means not knowing what one feels, having no words for it beyond fine or tired, and meeting any question about one's feelings with a blank."}
 ]}

{"candidate": {"label": "supple", "description": "This means moving with a loose, limber body that bends and stretches easily, so that one's frame stays flexible and fluid in every motion."},
 "traits": [
  {"id": 1, "label": "lighthearted", "description": "This means being lighthearted as a matter of disposition: speaking breezily and informally, quick to joke, carrying nothing heavily, and bringing the same easy lightness to large matters as to small ones."},
  {"id": 2, "label": "malleable", "description": "This means easily shifting one's opinions, plans and loyalties to match whoever is speaking most forcefully, yielding to pressure from others rather than holding a firm position of one's own."}
 ]}

{"candidate": {"label": "wind-swift", "description": "This means moving and running at great speed as a standing habit, covering ground quickly and never dawdling in any task or journey."},
 "traits": [
  {"id": 1, "label": "job-hopping", "description": "This means changing employers every year or two, always eyeing the job ads, and leaving the moment a better offer comes."},
  {"id": 2, "label": "company-loyal", "description": "This means staying with one employer from first job to retirement, never reading the job ads, and turning down every outside offer."},
  {"id": 3, "label": "manic", "description": "This means having a manic temperament: always at full tilt, racing from one idea to the next, talking fast without pause, elated about everything, and sure of one's own brilliance."},
  {"id": 4, "label": "restless", "description": "This means being unable to settle, fidgeting through any quiet moment, mind and hands always reaching for the next thing, and finding stillness uncomfortable even when nothing is wrong."}
 ]}
